// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    Recorder rec;

    function setUp() public { 
        c = new demo();
        rec = new Recorder();
    }

    // fuzz the from address, one recipient in the array encoded via length 1, and a value
    function testFuzz_property(address from, address dummy, uint256 v) public {
        // We must ensure that the recipient we pass is the recorder we control, and keep domain wide.
        // Use `dummy` only to satisfy fuzzer having multiple inputs; the actual callee is rec.
        address callee = address(rec);

        // construct single-element array of recipients in memory
        address[] memory tos = new address[](1);
        tos[0] = callee; // ensure c calls our recorder

        // Precondition: tos length > 0 always satisfied

        // Call transfer and ignore revert (it shouldn't revert in either version), observe what recorder logged
        bool ok;
        try c.transfer(from, callee, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always calls transferFrom(from, to, v) selector, so our recorder's
        // transferFromCalled must be true after the call for ALL inputs. The mutant that uses a different
        // selector will not hit transferFrom and so transferFromCalled will be false for some inputs.
        // Assert that transferFrom was called (this must hold for the reference for all inputs,
        // and will fail for the mutant for some fuzzed inputs).
        assertTrue(rec.transferFromCalled(), "expected transferFrom to have been called");

        // Additionally, sanity-check that the call did not revert (the reference shouldn't revert).
        assertTrue(ok, "transfer reverted unexpectedly");
    }
}

// Recorder that defines the transferFrom signature exactly so ABI decoding happens and is recorded.
contract Recorder {
    bool public transferFromCalled;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // Define the exact target function that C (reference) encodes with selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        transferFromCalled = true;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }

    // Also define a different function matching the mutant's selector so the call will not hit transferFrom if mutant used different selector.
    // This is optional but harmless; if mutant calls transfer(address,address,uint256) it will hit this instead.
    function transfer(address a, address b, uint256 c) external returns (bool) {
        // do nothing special; do not set transferFromCalled so difference is observable
        return true;
    }
}
